def eventualSafeNodes(graph):
    n = len(graph)
    rev = [[] for _ in range(n)]
    remaining = [len(graph[i]) for i in range(n)]
    for i in range(n):
        for j in graph[i]:
            rev[j].append(i)
    stack = [i for i in range(n) if remaining[i] == 0]
    safe = []
    while stack:
        j = stack.pop()
        safe.append(j)
        for i in rev[j]:
            remaining[i] -= 1
            if remaining[i] == 0:
                stack.append(i)
    return sorted(safe)
